#!/usr/bin/env node
/**
 * download-cloud-icons.mjs
 *
 * Replaces the Heroicons-based placeholder icons in shapes/aws/, shapes/gcp/,
 * and shapes/azure/ with their official, branded equivalents.
 *
 * The placeholder icons generated by sync-icons.mjs are functional and look
 * clean in the 3D renderer, but use generic Heroicons shapes. Run THIS script
 * once to replace them with official service icons.
 *
 * ─── AWS Architecture Icons ───────────────────────────────────────────────
 * License: CC-BY-ND 4.0 (attribution required, no derivatives)
 * Download: https://aws.amazon.com/architecture/icons/
 *   1. Download the "AWS Architecture Icons" ZIP from the link above.
 *   2. Place the extracted folder at:  /tmp/aws-icons/
 *   3. Run:  node scripts/download-cloud-icons.mjs --aws /tmp/aws-icons
 *
 * ─── Google Cloud Icons ───────────────────────────────────────────────────
 * License: Apache 2.0
 * Download: https://cloud.google.com/icons
 *   1. Download the "Google Cloud Architecture Diagramming Icons" ZIP.
 *   2. Place the extracted folder at:  /tmp/gcp-icons/
 *   3. Run:  node scripts/download-cloud-icons.mjs --gcp /tmp/gcp-icons
 *
 * ─── Azure Architecture Icons ─────────────────────────────────────────────
 * License: Microsoft Azure Icons terms of use
 * Download: https://learn.microsoft.com/en-us/azure/architecture/icons/
 *   1. Accept the terms of use on the download page.
 *   2. Place the extracted folder at:  /tmp/azure-icons/
 *   3. Run:  node scripts/download-cloud-icons.mjs --azure /tmp/azure-icons
 *
 * ─── Usage ────────────────────────────────────────────────────────────────
 *   node scripts/download-cloud-icons.mjs --aws /tmp/aws-icons
 *   node scripts/download-cloud-icons.mjs --gcp /tmp/gcp-icons
 *   node scripts/download-cloud-icons.mjs --azure /tmp/azure-icons
 *   node scripts/download-cloud-icons.mjs --aws /tmp/aws-icons --gcp /tmp/gcp-icons --azure /tmp/azure-icons
 *
 * After running, the official icons will overwrite the Heroicons placeholders.
 * Re-running sync-icons.mjs with --force will restore the placeholders.
 */

import { existsSync, readdirSync, copyFileSync, mkdirSync } from 'fs';
import { resolve, extname, basename } from 'path';
import { fileURLToPath } from 'url';

const __dirname = fileURLToPath(new URL('.', import.meta.url));
const ROOT = resolve(__dirname, '..');
const SHAPES = resolve(ROOT, 'apps/examples/public/assets/shapes');

// ─── AWS icon file → our naming convention ───────────────────────────────────
// The official AWS pack uses names like "Arch_Amazon-EC2_64.svg"
// Map our shape keys to the expected fragment in the official filename.
const AWS_FILENAME_FRAGMENTS = {
  'ec2':                    'Amazon-EC2',
  'ecs':                    'Amazon-ECS',
  'eks':                    'Amazon-EKS',
  'lambda':                 'AWS-Lambda',
  'fargate':                'AWS-Fargate',
  'lightsail':              'Amazon-Lightsail',
  'batch':                  'AWS-Batch',
  'app-runner':             'AWS-App-Runner',
  'outposts':               'AWS-Outposts',
  's3':                     'Amazon-S3',
  'efs':                    'Amazon-EFS',
  'fsx':                    'Amazon-FSx',
  'glacier':                'Amazon-S3-Glacier',
  'backup':                 'AWS-Backup',
  'storage-gateway':        'AWS-Storage-Gateway',
  'rds':                    'Amazon-RDS',
  'aurora':                 'Amazon-Aurora',
  'dynamodb':               'Amazon-DynamoDB',
  'elasticache':            'Amazon-ElastiCache',
  'redshift':               'Amazon-Redshift',
  'neptune':                'Amazon-Neptune',
  'documentdb':             'Amazon-DocumentDB',
  'timestream':             'Amazon-Timestream',
  'keyspaces':              'Amazon-Keyspaces',
  'qldb':                   'Amazon-QLDB',
  'vpc':                    'Amazon-VPC',
  'alb':                    'Elastic-Load-Balancing',
  'cloudfront':             'Amazon-CloudFront',
  'route53':                'Amazon-Route-53',
  'direct-connect':         'AWS-Direct-Connect',
  'transit-gateway':        'AWS-Transit-Gateway',
  'waf':                    'AWS-WAF',
  'shield-service':         'AWS-Shield',
  'nat-gateway':            'Amazon-VPC_NAT-Gateway',
  'global-accelerator':     'AWS-Global-Accelerator',
  'privatelink':            'AWS-PrivateLink',
  'sqs':                    'Amazon-SQS',
  'sns':                    'Amazon-SNS',
  'api-gateway':            'Amazon-API-Gateway',
  'step-functions':         'AWS-Step-Functions',
  'eventbridge':            'Amazon-EventBridge',
  'msk':                    'Amazon-MSK',
  'kinesis':                'Amazon-Kinesis',
  'appflow':                'Amazon-AppFlow',
  'mq':                     'Amazon-MQ',
  'appsync':                'AWS-AppSync',
  'iam':                    'AWS-IAM',
  'cognito':                'Amazon-Cognito',
  'kms':                    'AWS-KMS',
  'secrets-manager':        'AWS-Secrets-Manager',
  'certificate-manager':    'AWS-Certificate-Manager',
  'guardduty':              'Amazon-GuardDuty',
  'security-hub':           'AWS-Security-Hub',
  'inspector':              'Amazon-Inspector',
  'macie':                  'Amazon-Macie',
  'codepipeline':           'AWS-CodePipeline',
  'codebuild':              'AWS-CodeBuild',
  'codedeploy':             'AWS-CodeDeploy',
  'cloud9':                 'AWS-Cloud9',
  'x-ray':                  'AWS-X-Ray',
  'cloudwatch':             'Amazon-CloudWatch',
  'cloudtrail':             'AWS-CloudTrail',
  'cloudformation':         'AWS-CloudFormation',
  'systems-manager':        'AWS-Systems-Manager',
  'control-tower':          'AWS-Control-Tower',
  'organizations':          'AWS-Organizations',
  'amplify':                'AWS-Amplify',
  'athena':                 'Amazon-Athena',
  'glue':                   'AWS-Glue',
  'emr':                    'Amazon-EMR',
  'quicksight':             'Amazon-QuickSight',
  'lakeformation':          'AWS-Lake-Formation',
  'kinesis-data-analytics': 'Amazon-Kinesis-Data-Analytics',
  'opensearch':             'Amazon-OpenSearch-Service',
  'datazone':               'Amazon-DataZone',
  'sagemaker':              'Amazon-SageMaker',
  'bedrock':                'Amazon-Bedrock',
  'rekognition':            'Amazon-Rekognition',
  'polly':                  'Amazon-Polly',
  'transcribe':             'Amazon-Transcribe',
  'translate':              'Amazon-Translate',
  'comprehend':             'Amazon-Comprehend',
  'textract':               'Amazon-Textract',
  'iot-core':               'AWS-IoT-Core',
  'greengrass':             'AWS-IoT-Greengrass',
  'ivs':                    'Amazon-Interactive-Video-Service',
};

/** Recursively list all SVG files in a directory tree. */
function findSvgs(dir) {
  const results = [];
  if (!existsSync(dir)) return results;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = resolve(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...findSvgs(full));
    } else if (extname(entry.name).toLowerCase() === '.svg') {
      results.push(full);
    }
  }
  return results;
}

function processAws(srcRoot) {
  console.log(`\n🔍 Scanning AWS icons in: ${srcRoot}`);
  const allSvgs = findSvgs(srcRoot);
  console.log(`   Found ${allSvgs.length} SVG files.`);
  const destDir = resolve(SHAPES, 'aws');
  mkdirSync(destDir, { recursive: true });
  let matched = 0;

  for (const [ourKey, fragment] of Object.entries(AWS_FILENAME_FRAGMENTS)) {
    const lc = fragment.toLowerCase();
    const match = allSvgs.find(p => basename(p).toLowerCase().includes(lc));
    if (match) {
      copyFileSync(match, resolve(destDir, `${ourKey}.svg`));
      matched++;
    } else {
      console.warn(`  ⚠ Not found: ${ourKey} (looked for fragment: ${fragment})`);
    }
  }
  console.log(`✅ AWS: matched ${matched}/${Object.keys(AWS_FILENAME_FRAGMENTS).length} icons.`);
}

function processGcp(srcRoot) {
  console.log(`\n🔍 Scanning GCP icons in: ${srcRoot}`);
  const allSvgs = findSvgs(srcRoot);
  console.log(`   Found ${allSvgs.length} SVG files.`);
  const destDir = resolve(SHAPES, 'gcp');
  mkdirSync(destDir, { recursive: true });

  // GCP icons use descriptive names; try to match by our key embedded in filename.
  const GCP_KEYS = [
    'compute-engine', 'cloud-run', 'bigquery', 'cloud-storage', 'pubsub',
    'gke', 'cloud-functions', 'cloud-sql', 'cloud-spanner', 'firebase',
    'firestore', 'bigtable', 'dataflow', 'dataproc', 'vertex-ai',
    'cloud-build', 'artifact-registry', 'cloud-dns', 'cloud-armor',
    'cloud-nat', 'vpc-network', 'load-balancing', 'secret-manager', 'iam',
    'cloud-monitoring', 'cloud-logging', 'cloud-trace', 'memorystore',
    'workflows', 'eventarc', 'apigee', 'cloud-cdn', 'looker',
    'alloydb', 'datastream', 'dataform', 'cloud-run-jobs',
    'cloud-scheduler', 'cloud-tasks', 'identity-platform',
  ];
  let matched = 0;
  for (const key of GCP_KEYS) {
    const needle = key.replace(/-/g, '').toLowerCase();
    const match = allSvgs.find(p => basename(p).toLowerCase().replace(/[-_]/g, '').includes(needle));
    if (match) {
      copyFileSync(match, resolve(destDir, `${key}.svg`));
      matched++;
    } else {
      console.warn(`  ⚠ Not found: gcp:${key}`);
    }
  }
  console.log(`✅ GCP: matched ${matched}/${GCP_KEYS.length} icons.`);
}

function processAzure(srcRoot) {
  console.log(`\n🔍 Scanning Azure icons in: ${srcRoot}`);
  const allSvgs = findSvgs(srcRoot);
  console.log(`   Found ${allSvgs.length} SVG files.`);
  const destDir = resolve(SHAPES, 'azure');
  mkdirSync(destDir, { recursive: true });

  const AZURE_KEYS = [
    'virtual-machine', 'app-service', 'functions', 'aks', 'container-instances',
    'batch', 'spring-apps', 'storage-account', 'blob-storage', 'data-lake',
    'managed-disk', 'files', 'sql-database', 'cosmos-db', 'cache-for-redis',
    'database-for-postgres', 'synapse-analytics', 'database-for-mysql',
    'virtual-network', 'load-balancer', 'application-gateway', 'front-door',
    'cdn', 'vpn-gateway', 'firewall', 'dns', 'private-link', 'nat-gateway',
    'service-bus', 'event-hubs', 'event-grid', 'logic-apps', 'api-management',
    'service-connector', 'active-directory', 'key-vault', 'defender',
    'sentinel', 'ddos-protection', 'devops', 'pipelines', 'repos', 'boards',
    'cognitive-services', 'openai', 'machine-learning', 'bot-service',
    'monitor', 'policy', 'resource-groups', 'cost-management', 'automation',
    'data-factory', 'databricks', 'stream-analytics', 'analysis-services',
  ];
  let matched = 0;
  for (const key of AZURE_KEYS) {
    const needle = key.replace(/-/g, '').toLowerCase();
    const match = allSvgs.find(p => basename(p).toLowerCase().replace(/[-_]/g, '').includes(needle));
    if (match) {
      copyFileSync(match, resolve(destDir, `${key}.svg`));
      matched++;
    } else {
      console.warn(`  ⚠ Not found: azure:${key}`);
    }
  }
  console.log(`✅ Azure: matched ${matched}/${AZURE_KEYS.length} icons.`);
}

// ─── CLI ─────────────────────────────────────────────────────────────────────

const args = process.argv.slice(2);
let ran = false;

for (let i = 0; i < args.length; i++) {
  if (args[i] === '--aws' && args[i + 1]) {
    processAws(resolve(args[++i]));
    ran = true;
  } else if (args[i] === '--gcp' && args[i + 1]) {
    processGcp(resolve(args[++i]));
    ran = true;
  } else if (args[i] === '--azure' && args[i + 1]) {
    processAzure(resolve(args[++i]));
    ran = true;
  }
}

if (!ran) {
  console.log(`
Usage:
  node scripts/download-cloud-icons.mjs --aws   <path-to-aws-icons>
  node scripts/download-cloud-icons.mjs --gcp   <path-to-gcp-icons>
  node scripts/download-cloud-icons.mjs --azure <path-to-azure-icons>

Download the official icon packs first:
  AWS:   https://aws.amazon.com/architecture/icons/       (CC-BY-ND 4.0)
  GCP:   https://cloud.google.com/icons                   (Apache 2.0)
  Azure: https://learn.microsoft.com/en-us/azure/architecture/icons/  (Microsoft terms)
`);
}
